            return False

        char_count = {}
        for char in s:
            char_count[char] = char_count.get(char, 0) + 1

        # Check for two identical characters
        for count in char_count.values():
            if count >= 2:
                del_char = count // 2
                remaining_string = s[:del_char] + s[delt_char+1:]
                if remaining_string == '':
