def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    def dfs(node: int, visited: Set[int]) -> int:
        visited.add(node)
        count = 1  # starting with the root node
        for neighbor in edges[node]:
            if neighbor not in visited:
                count += dfs(neighbor, visited)
        return count

    def degree(vertex: int) -> int:
        return len(neighbors(vertex))

    def neighbors(vertex: int) -> List[int]:
        return [neighbor for neighbor, _ in edges if neighbor == vertex]

    def is_alkane(vertices: List[int], max_count: int) -> bool:
        for vertex in vertices:
            if degree(vertex) not in {1, 4} or not any(degree(v) == 4 for v in neighbors(vertex)):
                return False
        return max_count >= 1

    visited = set()
    max_count = 0

    for node in range(1, n + 1):
        if node not in visited:
            count = dfs(node, visited)
            if count > max_count:
                max_count = count
            if is_alkane(neighbors(node), max_count):
                max_count = count

    return max_count if max_count > 0 else -1

