    def count_moves(current_stair, jump):
        if current_stair == 0:
            return 1  # One way to stay at the starting stair (do nothing)

        if (current_stair, jump) in memo:
            return memo[(current_stair, jump)]

        total_ways = 0

        for previous_jump in range(jump - 1, -1, -1):
            if previous_jump >= 0:
                total_ways += count_moves(current_stair - 1, previous_jump)
